INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(301759, 21986, 772, '<td valign="top">Interesting use of green and red... the complementary color theme would pop a little harder if the green wasnt'' overpowering the red so much.  The background in this shot is also showing through in a very weak way... maybe more of the background or less of it would enhance the image as well.  Good composition and decent choice of subject as well... = 6</td>', 'Interesting use of green and red... the complementary color theme would pop a little harder if the green wasnt'' overpowering the red so much.  The background in this shot is also showing through in a very weak way... maybe more of the background or less of it would enhance the image as well.  Good composition and decent choice of subject as well... = 6', '2003-05-19 01:11:01.000000', NULL, 1),
(301761, 21803, 772, '<td valign="top">beautiful landscape... the exposure on this shot is excellent and I also like the way the tree is framing the right side of the photo... excellent composition and very nice color as well... = 7</td>', 'beautiful landscape... the exposure on this shot is excellent and I also like the way the tree is framing the right side of the photo... excellent composition and very nice color as well... = 7', '2003-05-19 01:12:10.000000', NULL, 1),
(301762, 21852, 6325, '<td valign="top">Well exposed. Good simple composition.</td>', 'Well exposed. Good simple composition.', '2003-05-19 01:12:35.000000', NULL, 1),
(301763, 21938, 1717, '<td valign="top">beautiful!  it has a 3D look to it and i love the soft feel.  well done!</td>', 'beautiful!  it has a 3D look to it and i love the soft feel.  well done!', '2003-05-19 01:12:38.000000', NULL, 1),
(301765, 21774, 772, '<td valign="top">I can''t see where this photo meets the challenge... I am also having trouble finding interest in what I''m looking at.... = 1</td>', 'I can''t see where this photo meets the challenge... I am also having trouble finding interest in what I''m looking at.... = 1', '2003-05-19 01:13:42.000000', NULL, 1),
(301767, 21954, 772, '<td valign="top">complementary colors for sure.... subjectively, a bit uninteresting to me personally.  some of the straws appear to have dirt specs on them and the alignment doesn''t seem to work well, especially on the green ones... = 4</td>', 'complementary colors for sure.... subjectively, a bit uninteresting to me personally.  some of the straws appear to have dirt specs on them and the alignment doesn''t seem to work well, especially on the green ones... = 4', '2003-05-19 01:15:19.000000', NULL, 1),
(301771, 21641, 5999, '<td valign="top">Excellent shot, the lighting just seems a bit too harsh.</td>', 'Excellent shot, the lighting just seems a bit too harsh.', '2003-05-19 01:17:06.000000', NULL, 1),
(301772, 21965, 3981, '<td valign="top">Thrillingly gorgeous.  I''ve never seen a more beautiful flower shot.  Good luck!</td>', 'Thrillingly gorgeous.  I''ve never seen a more beautiful flower shot.  Good luck!', '2003-05-19 01:18:15.000000', NULL, 1),
(301773, 21826, 772, '<td valign="top">good use of complementary colors... I don''t particularly care for the long narrow composition... I think this image could be stronger showing more of the peppers... the lighting is good but the detail in the green is overpowering the ''flatness'' of the red... maybe a different perspective on the red would balance that a little more... = 6</td>', 'good use of complementary colors... I don''t particularly care for the long narrow composition... I think this image could be stronger showing more of the peppers... the lighting is good but the detail in the green is overpowering the ''flatness'' of the red... maybe a different perspective on the red would balance that a little more... = 6', '2003-05-19 01:18:19.000000', NULL, 1),
(301774, 21949, 5999, '<td valign="top">Sharp focus, great DOF, lovely colors. Great shot.<br/>Mark</td>', 'Sharp focus, great DOF, lovely colors. Great shot.Mark', '2003-05-19 01:18:30.000000', NULL, 1),
(301777, 21843, 772, '<td valign="top">good use of strong color...  good job with the exposure as well... this makes a good abstract, and I also like the fact that you didn''t let the diagonal split the frame in each corner... that is a good compositional strength in this photo... = 7</td>', 'good use of strong color...  good job with the exposure as well... this makes a good abstract, and I also like the fact that you didn''t let the diagonal split the frame in each corner... that is a good compositional strength in this photo... = 7', '2003-05-19 01:20:07.000000', NULL, 1),
(301778, 21947, 3981, '<td valign="top">Sensational lighting!  Colors are beautiful.  Focus and Composition are near perfect.</td>', 'Sensational lighting!  Colors are beautiful.  Focus and Composition are near perfect.', '2003-05-19 01:20:59.000000', NULL, 1),
(301780, 21983, 772, '<td valign="top">nice abstract and good use of two complementary colors... I believe that a darker background in the top right could help accent these colors even more... = 6</td>', 'nice abstract and good use of two complementary colors... I believe that a darker background in the top right could help accent these colors even more... = 6', '2003-05-19 01:21:25.000000', NULL, 1),
(301782, 21922, 772, '<td valign="top">excellent complementary colors... good use of shallow depth of field in a strong composition as well... technically well executed, but the subject matter doesn''t seem to really inspire me in a strong way... = 6</td>', 'excellent complementary colors... good use of shallow depth of field in a strong composition as well... technically well executed, but the subject matter doesn''t seem to really inspire me in a strong way... = 6', '2003-05-19 01:22:54.000000', NULL, 1),
(301785, 21857, 1717, '<td valign="top">this is a precious photo!  the facial expressions are priceless.  nice, bright colors and clear focus.  well done!</td>', 'this is a precious photo!  the facial expressions are priceless.  nice, bright colors and clear focus.  well done!', '2003-05-19 01:23:42.000000', NULL, 1),
(301786, 21852, 772, '<td valign="top">very nice composition and use of complementary colors... I would have possibly rotated the green apple a little to hide the blemish on the left side of it... = 6</td>', 'very nice composition and use of complementary colors... I would have possibly rotated the green apple a little to hide the blemish on the left side of it... = 6', '2003-05-19 01:24:16.000000', NULL, 1),
(301787, 21992, 7504, '<td valign="top">This might not do well with the colorblind people.  : )</td>', 'This might not do well with the colorblind people.  : )', '2003-05-19 01:24:43.000000', NULL, 1),
(301790, 21885, 772, '<td valign="top">very interesting theme here and good complementary color as well... this will be a good candidate for a ''how did they do that'' article... the impact from this photo comes more from technique than subject choice... = 6</td>', 'very interesting theme here and good complementary color as well... this will be a good candidate for a ''how did they do that'' article... the impact from this photo comes more from technique than subject choice... = 6', '2003-05-19 01:26:21.000000', NULL, 1),
(301791, 21781, 772, '<td valign="top">Challenge met... subjectively uninspiring for me.  I can''t really find much interest in what i''m looking at, but it is better than a literal composition of some sort... = 3</td>', 'Challenge met... subjectively uninspiring for me.  I can''t really find much interest in what i''m looking at, but it is better than a literal composition of some sort... = 3', '2003-05-19 01:27:29.000000', NULL, 1),
(301792, 21894, 772, '<td valign="top">very nice abstract... the complementary color here is very strong.  excellent composition as well... = 8</td>', 'very nice abstract... the complementary color here is very strong.  excellent composition as well... = 8', '2003-05-19 01:29:11.000000', NULL, 1),
(301793, 21500, 772, '<td valign="top">nice long exposure... the complementary colors are apparent, but they don''t seem to be the theme of the shot or enhance the shot in any way.  I think there are probably a lot of good composition opportunities of this scene with just the fountain... = 6</td>', 'nice long exposure... the complementary colors are apparent, but they don''t seem to be the theme of the shot or enhance the shot in any way.  I think there are probably a lot of good composition opportunities of this scene with just the fountain... = 6', '2003-05-19 01:31:05.000000', NULL, 1),
(301798, 21931, 772, '<td valign="top">I see the green and red, but here is not really enough red in this shot to create a nice theme of complementary colors... = 5</td>', 'I see the green and red, but here is not really enough red in this shot to create a nice theme of complementary colors... = 5', '2003-05-19 01:38:27.000000', NULL, 1),
(301799, 21661, 772, '<td valign="top">complementary colors are visible... this shot just seems uninteresting to me though... it''s a good non literal representation of your idea though... = 4</td>', 'complementary colors are visible... this shot just seems uninteresting to me though... it''s a good non literal representation of your idea though... = 4', '2003-05-19 01:39:23.000000', NULL, 1),
(301800, 21714, 772, '<td valign="top">I think the sky reflection is probably hurting this shot more than anything... the blue is a bit too dark for my taste and the reds are quite hot... my sony has trouble with reds in sunlight... maybe this is a sony shot... :) = 5</td>', 'I think the sky reflection is probably hurting this shot more than anything... the blue is a bit too dark for my taste and the reds are quite hot... my sony has trouble with reds in sunlight... maybe this is a sony shot... :) = 5', '2003-05-19 01:40:31.000000', NULL, 1),
(301802, 21952, 772, '<td valign="top">good use of complementary color... the theme works well.  I believe the depth of field is a bit too shallow for this particular shot.  I can''t see any purpose in the blue candy being soft in this shot... the sugar also has quite a few hot spots in it... maybe the shot is just a tad over exposed... = 5</td>', 'good use of complementary color... the theme works well.  I believe the depth of field is a bit too shallow for this particular shot.  I can''t see any purpose in the blue candy being soft in this shot... the sugar also has quite a few hot spots in it... maybe the shot is just a tad over exposed... = 5', '2003-05-19 01:42:48.000000', NULL, 1),
(301825, 21911, 6019, '<td valign="top">nicely done!!  clever use of colour</td>', 'nicely done!!  clever use of colour', '2003-05-19 02:30:02.000000', NULL, 1),
(301829, 21978, 6565, '<td valign="top">This is a very interesting, almost haunting photo!  I like the simplicity of it a lot!</td>', 'This is a very interesting, almost haunting photo!  I like the simplicity of it a lot!', '2003-05-19 03:02:45.000000', NULL, 1),
(301830, 21988, 6565, '<td valign="top">Nice perspective!</td>', 'Nice perspective!', '2003-05-19 03:03:08.000000', NULL, 1),
(301833, 21714, 6565, '<td valign="top">I like how the use of the mirror and sky make the jacks feel as though they''ve been tossed into the air!</td>', 'I like how the use of the mirror and sky make the jacks feel as though they''ve been tossed into the air!', '2003-05-19 03:05:56.000000', NULL, 1),
(301842, 21920, 6019, '<td valign="top">superb! well done!</td>', 'superb! well done!', '2003-05-19 04:11:00.000000', NULL, 1),
(301854, 21978, 8533, '<td valign="top">I think this might have worked better if the picture were closer to the subject and more centred on it.</td>', 'I think this might have worked better if the picture were closer to the subject and more centred on it.', '2003-05-19 05:15:53.000000', NULL, 1),
(301855, 21965, 4055, '<td valign="top">Lovely shot! Composition, colors and focus are all very good. So is the border. Well done and good luck in the Challenge L.</td>', 'Lovely shot! Composition, colors and focus are all very good. So is the border. Well done and good luck in the Challenge L.', '2003-05-19 05:16:36.000000', NULL, 1),
(301856, 21995, 8533, '<td valign="top">Nothing seems to be completely in focus, unfortunately</td>', 'Nothing seems to be completely in focus, unfortunately', '2003-05-19 05:17:21.000000', NULL, 1),
(301857, 21932, 8533, '<td valign="top">Nice job of getting the flame to show up well.</td>', 'Nice job of getting the flame to show up well.', '2003-05-19 05:17:54.000000', NULL, 1),
(301858, 21857, 8533, '<td valign="top">A GREAT shot but it doesn''t really seem like the colours are that important so I feel it''s lacking as a picture for this challenge.</td>', 'A GREAT shot but it doesn''t really seem like the colours are that important so I feel it''s lacking as a picture for this challenge.', '2003-05-19 05:21:07.000000', NULL, 1),
(301864, 21929, 6019, '<td valign="top">a bit more green would have made this a definite winner in my book!!</td>', 'a bit more green would have made this a definite winner in my book!!', '2003-05-19 06:39:36.000000', NULL, 1),
(301867, 21852, 6999, '<td valign="top">That red cloth allows the green to really jump out, but it has a muting effect on the red apple - still think it''s a good shot, but did you try other background colours? Like a rich deep blue, almost black is what I''d have tried. Nice shooting</td>', 'That red cloth allows the green to really jump out, but it has a muting effect on the red apple - still think it''s a good shot, but did you try other background colours? Like a rich deep blue, almost black is what I''d have tried. Nice shooting', '2003-05-19 06:54:58.000000', NULL, 1),
(301869, 21911, 6999, '<td valign="top">Good capture - and good thinking. The non-frelected skyy ruins this for me though - especially that green/blue cast from being slightly over-exposed (this may just be a personal bugbear of mine. Did you try cropping it out? I''d have thought that just the building and windows, with that one slightly open window to upset the regularity, would have made a fabulous shot. Good wrk, nevertheless.</td>', 'Good capture - and good thinking. The non-frelected skyy ruins this for me though - especially that green/blue cast from being slightly over-exposed (this may just be a personal bugbear of mine. Did you try cropping it out? I''d have thought that just the building and windows, with that one slightly open window to upset the regularity, would have made a fabulous shot. Good wrk, nevertheless.', '2003-05-19 06:58:27.000000', NULL, 1),
(301871, 21676, 6999, '<td valign="top">Interesting - real delicacy to that leaf, and the composition is quite daring, and quite effective. I have to lighten my screen to see the real detail though, so perhaps a touch more light on it would have been useful.</td>', 'Interesting - real delicacy to that leaf, and the composition is quite daring, and quite effective. I have to lighten my screen to see the real detail though, so perhaps a touch more light on it would have been useful.', '2003-05-19 07:01:54.000000', NULL, 1),
(301874, 21971, 6999, '<td valign="top">Harsh lighting - don''t much like those very bright reflections. Also i think this kind of shot needs very careful setting-up. With no other subjects whatsoever, the not-quite-symmetrical positioning is distracting.</td>', 'Harsh lighting - don''t much like those very bright reflections. Also i think this kind of shot needs very careful setting-up. With no other subjects whatsoever, the not-quite-symmetrical positioning is distracting.', '2003-05-19 07:03:54.000000', NULL, 1),
(301876, 21803, 6999, '<td valign="top">Like this very much - the capture of the edge highlights in those low clouds is wonderfully done, the tree is a nice balance to the sun, and the progression of the hills into the distance is nicely present too. I''d have done something about the noise in the blue sky - it''s really quite bad just above the clouds, but not ineradicable. Good work</td>', 'Like this very much - the capture of the edge highlights in those low clouds is wonderfully done, the tree is a nice balance to the sun, and the progression of the hills into the distance is nicely present too. I''d have done something about the noise in the blue sky - it''s really quite bad just above the clouds, but not ineradicable. Good work', '2003-05-19 07:07:32.000000', NULL, 1),
(301878, 21974, 6999, '<td valign="top">Just doesn''t quite seem completely sharp - presumably that macro DOF thing: the top of the flower is OK, but lower down the petals has started to go out of the field, which doesn''t dissociate the flower from the background in the way your title implies you wanted. It also seems more pink than green, but that''s only a minor point after all these colour challenges.</td>', 'Just doesn''t quite seem completely sharp - presumably that macro DOF thing: the top of the flower is OK, but lower down the petals has started to go out of the field, which doesn''t dissociate the flower from the background in the way your title implies you wanted. It also seems more pink than green, but that''s only a minor point after all these colour challenges.', '2003-05-19 07:10:14.000000', NULL, 1),
(301880, 21993, 772, '<td valign="top">This is an excellent attepmt at this shot... I know how difficult this one is.  The lighting is just a tad harsh which creates the hot spot on the right side of the glass and the stem...  I believe that the reflections on the glass have to be perfect in a shot like this.  The angle of the backlighting is letting your orange reflect on the top of the glass as well...  These glass reflections need to be a bit more subtle in my opinion... excellent attempt :) = 6</td>', 'This is an excellent attepmt at this shot... I know how difficult this one is.  The lighting is just a tad harsh which creates the hot spot on the right side of the glass and the stem...  I believe that the reflections on the glass have to be perfect in a shot like this.  The angle of the backlighting is letting your orange reflect on the top of the glass as well...  These glass reflections need to be a bit more subtle in my opinion... excellent attempt :) = 6', '2003-05-19 07:36:12.000000', NULL, 1),
(301884, 21990, 5999, '<td valign="top">Interesting, I think I would have like it more with more DOF.<br/>Mark</td>', 'Interesting, I think I would have like it more with more DOF.Mark', '2003-05-19 08:27:41.000000', NULL, 1),
(301885, 21843, 4493, '<td valign="top">Excellent abstract. I like your use of focus. 10 -danny</td>', 'Excellent abstract. I like your use of focus. 10 -danny', '2003-05-19 08:35:23.000000', NULL, 1),
(301886, 21578, 4493, '<td valign="top">The textures really set this off nicely. 10 -danny</td>', 'The textures really set this off nicely. 10 -danny', '2003-05-19 08:35:47.000000', NULL, 1),
(301887, 21824, 4493, '<td valign="top">Interesting work. The colors are perfect. Nice use of lighting. 10 -danny</td>', 'Interesting work. The colors are perfect. Nice use of lighting. 10 -danny', '2003-05-19 08:36:30.000000', NULL, 1),
(301888, 21753, 4493, '<td valign="top">This is a unique perspective on a flower shot. Good DOF and focus. 9 -danny</td>', 'This is a unique perspective on a flower shot. Good DOF and focus. 9 -danny', '2003-05-19 08:37:19.000000', NULL, 1),
(301889, 21948, 4493, '<td valign="top">Desaturation works well here. This is a very artsy shot. Excellent care taken to get the polls lined up properly. This must have been shot on an overcast day. 9 -danny</td>', 'Desaturation works well here. This is a very artsy shot. Excellent care taken to get the polls lined up properly. This must have been shot on an overcast day. 9 -danny', '2003-05-19 08:38:33.000000', NULL, 1),
(301890, 21960, 4493, '<td valign="top">Nice abstract. The line and colors work very well. Lighting and composition are all very strong. Good picture. 9 -danny</td>', 'Nice abstract. The line and colors work very well. Lighting and composition are all very strong. Good picture. 9 -danny', '2003-05-19 08:39:38.000000', NULL, 1),
(301891, 21978, 4493, '<td valign="top">Very nice work. The use of lighting to set the mood works very well. I like that the orange hand is not symmetrical with the blue. This adds interest to the shot. I wouldn''t mind just a bit more catch light in the front to illuminate the base of the blue hand more. Excellent work. 9 -danny</td>', 'Very nice work. The use of lighting to set the mood works very well. I like that the orange hand is not symmetrical with the blue. This adds interest to the shot. I wouldn''t mind just a bit more catch light in the front to illuminate the base of the blue hand more. Excellent work. 9 -danny', '2003-05-19 08:41:32.000000', NULL, 1),
(301894, 21741, 772, '<td valign="top">excellent use of complementary colors... This photo also offers some intrigue for how it was done :)  The exposure on this one seems a little hot overall.  The yellow cast on the chrome elements of the lighter seem to be working with the color theme... = 6</td>', 'excellent use of complementary colors... This photo also offers some intrigue for how it was done :)  The exposure on this one seems a little hot overall.  The yellow cast on the chrome elements of the lighter seem to be working with the color theme... = 6', '2003-05-19 08:42:53.000000', NULL, 1),
(301895, 21852, 4493, '<td valign="top">This is why I don''t vote from my laptop. This looks much much better on my monitor on my PC! This is a great still life. I love the velvet the apples are on. I don''t care for the green one being upside down, and the dead center composition. Still a very strong shot! 9 -danny</td>', 'This is why I don''t vote from my laptop. This looks much much better on my monitor on my PC! This is a great still life. I love the velvet the apples are on. I don''t care for the green one being upside down, and the dead center composition. Still a very strong shot! 9 -danny', '2003-05-19 08:43:17.000000', NULL, 1),
(301896, 21963, 772, '<td valign="top">interesting shot... the complementary color theme is here, but could possibly be stronger.. maybe creating a composition where there is more grass in the view would enhance the challenge theme some... = 5</td>', 'interesting shot... the complementary color theme is here, but could possibly be stronger.. maybe creating a composition where there is more grass in the view would enhance the challenge theme some... = 5', '2003-05-19 08:44:08.000000', NULL, 1),
(301897, 21502, 4493, '<td valign="top">Nice high key shot. Looks a little oversaturated on my monitor. Nice composition. 8 -danny</td>', 'Nice high key shot. Looks a little oversaturated on my monitor. Nice composition. 8 -danny', '2003-05-19 08:44:39.000000', NULL, 1),
(301898, 21947, 4493, '<td valign="top">The extreme lighting works nicely. I love the green in this shot, although I feel the complementary red is a little over lit as it looks purple. 8 -danny</td>', 'The extreme lighting works nicely. I love the green in this shot, although I feel the complementary red is a little over lit as it looks purple. 8 -danny', '2003-05-19 08:45:45.000000', NULL, 1),
(301900, 21949, 772, '<td valign="top">very nicely done... this is a strong composition and the complementary colors are very powerful in this image... It looks like a good product photo as well... makes me hungry :)  = 7</td>', 'very nicely done... this is a strong composition and the complementary colors are very powerful in this image... It looks like a good product photo as well... makes me hungry :)  = 7', '2003-05-19 08:46:20.000000', NULL, 1),
(301902, 21899, 4493, '<td valign="top">Simple and unique. A little more narrow of a crop would help accentuate the height in this shot. The added black on the left doesn''t add to the composition. Still a very strong shot. 8 -danny</td>', 'Simple and unique. A little more narrow of a crop would help accentuate the height in this shot. The added black on the left doesn''t add to the composition. Still a very strong shot. 8 -danny', '2003-05-19 08:46:52.000000', NULL, 1),
(301905, 21477, 772, '<td valign="top">excellent use of shallow depth of field... the complementary colors theme is strong as well.  this particular view has a nice surreal feeling to it with the thin plane of focus.  = 8</td>', 'excellent use of shallow depth of field... the complementary colors theme is strong as well.  this particular view has a nice surreal feeling to it with the thin plane of focus.  = 8', '2003-05-19 08:48:45.000000', NULL, 1),
(301906, 21676, 4493, '<td valign="top">Some may feel the darkness is a weakness to this shot, I however like the feel it brings. The dark red leaves with the hint of sun on them show the coming of cooler weather. I do feel that a more narrow crop would make for a stronger composition. I think that the added green is taking the eye away from the leaf. 8 -danny</td>', 'Some may feel the darkness is a weakness to this shot, I however like the feel it brings. The dark red leaves with the hint of sun on them show the coming of cooler weather. I do feel that a more narrow crop would make for a stronger composition. I think that the added green is taking the eye away from the leaf. 8 -danny', '2003-05-19 08:48:54.000000', NULL, 1),
(301907, 21500, 4493, '<td valign="top">Nice lighting, I would like to see a tighter shot where the fountain is the main part of the shot. As it is now, the surrounding buildings makes the shot feel cluttered. 8 -danny</td>', 'Nice lighting, I would like to see a tighter shot where the fountain is the main part of the shot. As it is now, the surrounding buildings makes the shot feel cluttered. 8 -danny', '2003-05-19 08:49:53.000000', NULL, 1),
(301908, 21803, 4493, '<td valign="top">Breautiful sunset shot. Nice colors. The tree in the foreground gives a nice sense of perspective. 8 -danny</td>', 'Breautiful sunset shot. Nice colors. The tree in the foreground gives a nice sense of perspective. 8 -danny', '2003-05-19 08:50:28.000000', NULL, 1),
(301909, 21578, 772, '<td valign="top">interesting abstract and excellent use of complementary colors.  it looks like some sort of modern art painting to me... I like the simple elegance in this image... The title leaves me with questions... = 7</td>', 'interesting abstract and excellent use of complementary colors.  it looks like some sort of modern art painting to me... I like the simple elegance in this image... The title leaves me with questions... = 7', '2003-05-19 08:51:06.000000', NULL, 1),
(301910, 21957, 4493, '<td valign="top">Simple, but effective. Well executed lighting and composition. 8 -danny</td>', 'Simple, but effective. Well executed lighting and composition. 8 -danny', '2003-05-19 08:51:24.000000', NULL, 1),
(301911, 21927, 4493, '<td valign="top">Interesting to look at. Composition is ok, although there may be more blue on the right then is needed. 8 -danny</td>', 'Interesting to look at. Composition is ok, although there may be more blue on the right then is needed. 8 -danny', '2003-05-19 08:52:19.000000', NULL, 1),
(301912, 21847, 4493, '<td valign="top">Go Team! :-) Nice focus and saturation. 7 -danny</td>', 'Go Team! :-) Nice focus and saturation. 7 -danny', '2003-05-19 08:53:04.000000', NULL, 1),
(301913, 21676, 772, '<td valign="top">very nice work with the shallow depth of field... I think the only real improvement that this image could use would be more light on the leaves... the dark leaves don''t really suppor the theme of complementary colors as well as they could.  Complementary colors usually offer a very strong contrast...  = 5</td>', 'very nice work with the shallow depth of field... I think the only real improvement that this image could use would be more light on the leaves... the dark leaves don''t really suppor the theme of complementary colors as well as they could.  Complementary colors usually offer a very strong contrast...  = 5', '2003-05-19 08:53:20.000000', NULL, 1),
(301914, 21988, 772, '<td valign="top">good complementary color here... interesting composition as well... subjectively, it leaves me asking for more... = 5</td>', 'good complementary color here... interesting composition as well... subjectively, it leaves me asking for more... = 5', '2003-05-19 08:54:10.000000', NULL, 1),
(301915, 21988, 4493, '<td valign="top">You must work at the bowling alley. Nice care taken to get your shot preped. The composition of the balls going straight down the middle isn''t working for me in landscape mode. Did you try a portrait crop so as to minimize the surrounding lanes? Your focus and lighting seem good. 7 -danny</td>', 'You must work at the bowling alley. Nice care taken to get your shot preped. The composition of the balls going straight down the middle isn''t working for me in landscape mode. Did you try a portrait crop so as to minimize the surrounding lanes? Your focus and lighting seem good. 7 -danny', '2003-05-19 08:54:54.000000', NULL, 1),
(301916, 21885, 4493, '<td valign="top">Not sure how you did this, but it''s cute non-the-less. The composition is perfect. I do wish there was more light on the shot. Maybe bringing the levels up would have helped. Nice shot. 7 -danny</td>', 'Not sure how you did this, but it''s cute non-the-less. The composition is perfect. I do wish there was more light on the shot. Maybe bringing the levels up would have helped. Nice shot. 7 -danny', '2003-05-19 08:56:13.000000', NULL, 1),
(301917, 21947, 772, '<td valign="top">beautiful calla lillies... i think the lighting on this shot is pretty good also... I think the part that is missing here is the complementary color theme.  purple and green aren''t complementary... purple and yellow are however... the yellow insides of the blossoms are not holding their color in this photo because of the angle of lighting...  = 6</td>', 'beautiful calla lillies... i think the lighting on this shot is pretty good also... I think the part that is missing here is the complementary color theme.  purple and green aren''t complementary... purple and yellow are however... the yellow insides of the blossoms are not holding their color in this photo because of the angle of lighting...  = 6', '2003-05-19 08:56:20.000000', NULL, 1),
(301918, 21986, 4493, '<td valign="top">The colors and background are very well done. There is something about the lighting on the plant that seems a little harsh compared to the softness of the vase and background. I''m wondering if a landscape crop with more negative space on the left would make for a stronger composition. Good pic.  7 -danny</td>', 'The colors and background are very well done. There is something about the lighting on the plant that seems a little harsh compared to the softness of the vase and background. I''m wondering if a landscape crop with more negative space on the left would make for a stronger composition. Good pic.  7 -danny', '2003-05-19 08:58:21.000000', NULL, 1),
(301919, 21503, 772, '<td valign="top">complementary colors are evident, but this is one of those photos that gives me no inspiration from the subject choice...  I also think that a slightly diagonal composition could make this particular shot a little stronger... = 5</td>', 'complementary colors are evident, but this is one of those photos that gives me no inspiration from the subject choice...  I also think that a slightly diagonal composition could make this particular shot a little stronger... = 5', '2003-05-19 08:59:19.000000', NULL, 1),
