(302617, 21803, 2560, '<td valign="top">very nice colors in this shot</td>', 'very nice colors in this shot', '2003-05-19 22:03:43.000000', NULL, 1),
(302630, 21857, 2560, '<td valign="top">you cant beat a picture with 4 kids having that much fun.</td>', 'you cant beat a picture with 4 kids having that much fun.', '2003-05-19 22:08:58.000000', NULL, 1),
(302633, 21885, 2344, '<td valign="top">This is very cute! Bump up the brightness/contrast/saturation and you''d have a better chance at winning</td>', 'This is very cute! Bump up the brightness/contrast/saturation and you''d have a better chance at winning', '2003-05-19 22:11:32.000000', NULL, 1),
(302636, 21930, 2560, '<td valign="top">This is a good shot all though not the most interesting(maybe its just not hot enough here yet).  Maybe try putting some lipstick on the glass or something.</td>', 'This is a good shot all though not the most interesting(maybe its just not hot enough here yet).  Maybe try putting some lipstick on the glass or something.', '2003-05-19 22:13:47.000000', NULL, 1),
(302639, 21954, 2560, '<td valign="top">The reds seem to run together at the top, Some shadow up there would help.</td>', 'The reds seem to run together at the top, Some shadow up there would help.', '2003-05-19 22:16:01.000000', NULL, 1),
(302642, 21831, 2560, '<td valign="top">very good DOF.</td>', 'very good DOF.', '2003-05-19 22:17:40.000000', NULL, 1),
(302645, 21756, 2560, '<td valign="top">I like the way the dof covers the whole subject.  You need a better shaped berry and remove some of the lighter colored green.  there are 4 if removed would improve the photo alot.</td>', 'I like the way the dof covers the whole subject.  You need a better shaped berry and remove some of the lighter colored green.  there are 4 if removed would improve the photo alot.', '2003-05-19 22:20:32.000000', NULL, 1),
(302653, 21477, 2560, '<td valign="top">I like this shot!  im not sure the forground stuff helps..</td>', 'I like this shot!  im not sure the forground stuff helps..', '2003-05-19 22:27:16.000000', NULL, 1),
(302657, 21947, 2560, '<td valign="top">This is good enough to be a Setzler shot but I think you cut the bottom off a hair.  congrats, i know this will do well.</td>', 'This is good enough to be a Setzler shot but I think you cut the bottom off a hair.  congrats, i know this will do well.', '2003-05-19 22:29:58.000000', NULL, 1),
(302658, 21922, 2560, '<td valign="top">nice shot,</td>', 'nice shot,', '2003-05-19 22:31:30.000000', NULL, 1),
(302660, 21502, 2560, '<td valign="top">Nice shot this one is a peach  :)</td>', 'Nice shot this one is a peach  :)', '2003-05-19 22:33:27.000000', NULL, 1),
