(305933, 21641, 2560, '<td valign="top">the  Lighting is to harsh.  use a diffuser in to block the direct sunlight if you can.</td>', 'the  Lighting is to harsh.  use a diffuser in to block the direct sunlight if you can.', '2003-05-24 00:29:37.000000', NULL, 1),
(305935, 21596, 2560, '<td valign="top">I think this composition would be a good time to use hyper focus.  Also a polorizer might let you get more saturation in the harsh sun.</td>', 'I think this composition would be a good time to use hyper focus.  Also a polorizer might let you get more saturation in the harsh sun.', '2003-05-24 00:37:11.000000', NULL, 1),
